import json
import math
from pathlib import Path

lab = json.loads(Path("assets/datasets/nsw/experiment_lab.json").read_text(encoding="utf-8"))
cohorts = lab["cohorts"]
treated = cohorts["treated"]

def mean_var(vals):
    m = sum(vals) / len(vals)
    sq = 0.0
    for v in vals:
        sq += (v - m) ** 2
    return m, sq / (len(vals) - 1)

def compute_smd(rows_t, rows_c, key):
    vt = []
    for r in rows_t:
        vt.append(float(r[key]))
    vc = []
    for r in rows_c:
        vc.append(float(r[key]))
    mt, var_t = mean_var(vt)
    mc, var_c = mean_var(vc)
    return (mt - mc) / math.sqrt((var_t + var_c) / 2.0)

def audit_pair(rows_t, rows_c):
    # Raw gap
    sum_t = 0.0
    for r in rows_t:
        sum_t += r["re78"]
    sum_c = 0.0
    for r in rows_c:
        sum_c += r["re78"]
    raw_gap = (sum_t / len(rows_t)) - (sum_c / len(rows_c))

    # 2-stratum (re74 > 0) Treated-weighted standardization
    adj_gap = 0.0
    for is_pos in [False, True]:
        tv = []
        for r in rows_t:
            if (r["re74"] > 0.0) == is_pos:
                tv.append(r["re78"])
        cv = []
        for r in rows_c:
            if (r["re74"] > 0.0) == is_pos:
                cv.append(r["re78"])
        w = len(tv) / len(rows_t)
        adj_gap += w * ((sum(tv) / len(tv)) - (sum(cv) / len(cv)))

    smd_re74 = compute_smd(rows_t, rows_c, "re74")
    return len(rows_c), raw_gap, adj_gap, smd_re74

for comp in ["experimental", "psid"]:
    n0, raw_g, adj_g, s74 = audit_pair(treated, cohorts[comp])
    print(f"{comp:12s} | n0={n0:4d} | raw_gap={raw_g:+10.2f} | adj_gap={adj_g:+10.2f} | SMD(re74)={s74:+.3f}")
